import{_ as t}from"./chunks/maquette.DAGKV7TO.js";import{_ as a,o as s,c as n,a2 as r}from"./chunks/framework.CQxpk36T.js";const u=JSON.parse('{"title":"Get started","description":"","frontmatter":{},"headers":[],"relativePath":"en/demarrer.md","filePath":"en/demarrer.md","lastUpdated":1793574169000}'),o={name:"en/demarrer.md"};function i(h,e,l,d,p,c){return s(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="get-started" tabindex="-1">Get started <a class="header-anchor" href="#get-started" aria-label="Permalink to &quot;Get started&quot;">​</a></h1><p>HAven draws your property in 3D, then connects it to <strong>Home Assistant</strong>, which stays the engine: HAven shows and controls, without automating anything itself. Without Home Assistant, a <strong>demo mode</strong> brings an example house to life with simulated devices.</p><div class="info custom-block"><p class="custom-block-title">Language</p><p>The HAven interface is in French. This documentation gives each French label with its meaning, for example the <strong>Tableau</strong> (dashboard) tab.</p></div><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><table tabindex="0"><thead><tr><th>To…</th><th>You need</th></tr></thead><tbody><tr><td>Run HAven</td><td><a href="https://nodejs.org" target="_blank" rel="noreferrer">Node.js</a> 22 or newer</td></tr><tr><td>Host it on a server</td><td><a href="https://www.docker.com/" target="_blank" rel="noreferrer">Docker</a></td></tr><tr><td>Fetch the land registry (France only)</td><td>Python 3, nothing else to install</td></tr><tr><td>Control the house</td><td>A <a href="https://www.home-assistant.io/" target="_blank" rel="noreferrer">Home Assistant</a> reachable from the browser</td></tr></tbody></table><p>On the browser side: a recent Safari, Chrome, Edge or Firefox with WebGL 2. Any phone from the last few years will do.</p><h2 id="install-and-run" tabindex="-1">Install and run <a class="header-anchor" href="#install-and-run" aria-label="Permalink to &quot;Install and run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/Chamallaw/HAven.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> HAven</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>Open <a href="http://localhost:5173" target="_blank" rel="noreferrer">http://localhost:5173</a>: the <strong>example house</strong> appears in <strong>demo mode</strong>. On a phone on the same network: <code>http://&lt;computer address&gt;:5173</code>.</p><p><img src="`+t+'" alt="The example house in the sun, in demo mode"></p><div class="tip custom-block"><p class="custom-block-title">First load</p><p>On the very first display, HAven precomputes the scene lighting (soft shadows, lanterns) in the background, then keeps it in the browser: later visits open instantly.</p></div><h2 id="demo-mode" tabindex="-1">Demo mode <a class="header-anchor" href="#demo-mode" aria-label="Permalink to &quot;Demo mode&quot;">​</a></h2><p>As long as no Home Assistant is connected, everything is simulated from the property description: a lamp per room, thermostats, the garage door, the chicken coop hatch, cars coming and going, and a complete solar installation with a battery and an electric car. You can touch everything; nothing leaves the browser.</p><p>In the <a href="/HAven-docs/en/interface#settings">settings</a>, demo mode also offers <strong>weather presets</strong> (sun, cloudy, rain, storm, snow, fog, gale) to see the model in every weather.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ol><li><strong><a href="/HAven-docs/en/interface">Tour the interface</a></strong>: tabs, time, weather, settings.</li><li><strong><a href="/HAven-docs/en/guide/">Describe your property</a></strong>: start from the example, lay out your land, your buildings, your rooms.</li><li><strong><a href="/HAven-docs/en/home-assistant/">Connect Home Assistant</a></strong>: the lights, shutters, heating and energy of the real house.</li><li><strong><a href="/HAven-docs/en/hebergement">Host it</a></strong> on a server at home, to have it on your phone like an app.</li></ol><p>Allow an evening for a first version of your property, then touch it up as you go.</p>',17)])])}const k=a(o,[["render",i]]);export{u as __pageData,k as default};
